import{_ as t,o as d,c as o,a3 as n}from"./chunks/framework.DWzkrVA3.js";const g=JSON.parse('{"title":"Konfiguration","description":"","frontmatter":{},"headers":[],"relativePath":"de/administration/configuration.md","filePath":"de/administration/configuration.md"}'),r={name:"de/administration/configuration.md"};function a(i,e,c,s,l,u){return d(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="konfiguration" tabindex="-1">Konfiguration <a class="header-anchor" href="#konfiguration" aria-label="Permalink to &quot;Konfiguration&quot;">​</a></h1><p>Der Server wird mit Umgebungsvariablen eingerichtet, die mit <code>ANTHOLOGY_</code> beginnen. In den Quadlet-Dateien sind es <code>Environment=</code>-Zeilen von <code>anthology-server.container</code>, in Compose stehen sie unter <code>environment:</code> von <code>anthology-server</code>.</p><h2 id="wichtige-einstellungen" tabindex="-1">Wichtige Einstellungen <a class="header-anchor" href="#wichtige-einstellungen" aria-label="Permalink to &quot;Wichtige Einstellungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Vorgabe</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>ANTHOLOGY_DATABASE_URL</code></td><td>vom Pod gesetzt</td><td>PostgreSQL-Verbindung; das Passwort kommt aus <code>ANTHOLOGY_DATABASE_PASSWORD_FILE</code></td></tr><tr><td><code>ANTHOLOGY_TIME_ZONE</code></td><td><code>UTC</code></td><td>Zeitzone der Zeitpläne, z. B. <code>Europe/Zurich</code></td></tr><tr><td><code>ANTHOLOGY_IMPORT_ROOTS</code></td><td><code>/data/imports</code></td><td>Ordner, aus denen Administratoren importieren dürfen, durch Kommas getrennt</td></tr><tr><td><code>ANTHOLOGY_MUSICBRAINZ_CONTACT</code></td><td>–</td><td>deine E-Mail oder URL, an MusicBrainz als verlangter Kontakt gesendet</td></tr><tr><td><code>ANTHOLOGY_ACOUSTID_API_KEY</code></td><td>–</td><td>schaltet Fingerabdruck-Abfragen bei AcoustID frei</td></tr><tr><td><code>ANTHOLOGY_MUSICBRAINZ_URL</code></td><td>–</td><td>ein lokaler MusicBrainz-Spiegel (ohne Ratenbegrenzung)</td></tr><tr><td><code>ANTHOLOGY_SOURCE_SERVICES</code></td><td>–</td><td>URLs der Quelldienste, durch Kommas getrennt</td></tr><tr><td><code>ANTHOLOGY_RAUMFELD_HOSTS</code></td><td>–</td><td>Adressen von Raumfeld-Hosts, wenn die Suche sie nicht findet</td></tr><tr><td><code>ANTHOLOGY_OUTPUT_MEDIA_URL</code></td><td>–</td><td>die Adresse des Servers, wie die Lautsprecher sie sehen</td></tr><tr><td><code>ANTHOLOGY_TRANSCODE_CACHE_GB</code></td><td><code>20</code></td><td>Grösse des Umwandlungs-Caches</td></tr><tr><td><code>ANTHOLOGY_THUMBNAIL_CACHE_MB</code></td><td><code>512</code></td><td>Grösse der Cover-Vorschaubilder</td></tr><tr><td><code>ANTHOLOGY_JOBS_THROTTLE</code></td><td><code>normal</code></td><td>gleichzeitige Hintergrundaufträge: <code>gentle</code>, <code>normal</code>, <code>fast</code></td></tr></tbody></table><h2 id="daten-volumes" tabindex="-1">Daten-Volumes <a class="header-anchor" href="#daten-volumes" aria-label="Permalink to &quot;Daten-Volumes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Volume</th><th>Eingehängt unter</th><th>Inhalt</th><th>Sichern</th></tr></thead><tbody><tr><td><code>anthology-library</code></td><td><code>/data/library</code></td><td>deine Musik (Originale) und die Coverbilder</td><td>ja</td></tr><tr><td><code>anthology-db</code></td><td>PostgreSQL</td><td>die Datenbank</td><td>ja (<code>pg_dump</code>)</td></tr><tr><td><code>anthology-keys</code></td><td><code>/data/keys</code></td><td>Signaturschlüssel; ohne sie sind alle Geräte abgemeldet</td><td>ja</td></tr><tr><td><code>anthology-imports</code></td><td><code>/data/imports</code></td><td>eingehende Dateien</td><td>optional</td></tr><tr><td><code>anthology-cache</code></td><td><code>/data/cache</code></td><td>Umwandlungen, getaggte Kopien, Vorschaubilder</td><td>nein</td></tr></tbody></table><p>Eine bestehende Sammlung kann das Bibliotheks-Volume durch einen Bind-Mount eines Host-Ordners ersetzen (<code>Volume=/srv/music:/data/library:Z</code>); Server und Tagger brauchen denselben Pfad.</p><h2 id="https-und-zugriff-von-aussen" tabindex="-1">HTTPS und Zugriff von aussen <a class="header-anchor" href="#https-und-zugriff-von-aussen" aria-label="Permalink to &quot;HTTPS und Zugriff von aussen&quot;">​</a></h2><p>Der Server spricht einfaches HTTP auf Port 8400. Für den Zugriff von ausserhalb deines Netzes stelle einen Reverse-Proxy mit TLS davor (etwa Caddy, Traefik oder nginx) und leite WebSocket-Upgrades für <code>/api/v1/ws</code> weiter. Der Server vertraut <code>X-Forwarded-*</code>-Kopfzeilen nur von <code>127.0.0.1</code>; läuft der Proxy anderswo, setze <code>FORWARDED_ALLOW_IPS</code> auf seine Adresse.</p>',9)])])}const _=t(r,[["render",a]]);export{g as __pageData,_ as default};
